  expect_identical(.pyrun(local({ rationalize(Rational(-22, 7)) })), "-22/7")
  expect_identical(.pyrun(local({ rationalize(Integer(5)) })), "5")
  expect_identical(.pyrun(local({ rationalize(Float('0.25')) })), "ERR TypeError: Invalid comparison of non-real zoo")
  expect_identical(.pyrun(local({ rationalize(Float('3.14159')) })), "314159/100000")
  expect_identical(.pyrun(local({ rationalize(Float(0.5)) })), "ERR TypeError: Invalid comparison of non-real zoo")
  expect_identical(.pyrun(local({ rationalize(Float(0.1)) })), "ERR TypeError: Invalid comparison of non-real zoo")
  expect_identical(.pyrun(local({ rationalize(Float('-1.75')) })), "ERR TypeError: Invalid comparison of non-real zoo")
